const c = it.contact;
const s = safeNode('Search Person');
const results = (s && Array.isArray(s.json.results)) ? s.json.results.slice(0, 12) : [];
const context = [
  '## CANDIDATE CONTACT',
  'Name: ' + c.name, 'Role (claimed): ' + (c.role || '?'), 'Seniority: ' + (c.seniority || '?'), 'Company: ' + (c.account_name || '?'),
