  '', '## LIVE SEARCH RESULTS',
  results.map(r => '- ' + r.title + ' :: ' + r.url + ' :: ' + (r.published || '') + ' :: ' + (r.snippet || '').slice(0, 300)).join('\n') || '(none)'
].join('\n');
